import { useState } from "react";
import { useTheme } from "../context/ThemeContext";
import { projects } from "../data/portfolio";
import { useScrollReveal } from "../hooks/useScrollReveal";
import { ImageGallery } from "./ProjectImage";

// ─────────────────────────────────────────────────────────────────────────────
// ProjectCard
// ─────────────────────────────────────────────────────────────────────────────
function ProjectCard({ project }) {
  const [expanded, setExpanded] = useState(false);
  const { ref, revealed } = useScrollReveal();
  const { theme } = useTheme();
  const isDark = theme === "dark";

  return (
    <article
      ref={ref}
      className={`${revealed ? "fade-up visible" : "fade-up"} border transition-colors duration-300
        ${isDark
          ? "border-wire bg-ink-800 hover:border-ink-500"
          : "border-wire-light bg-white hover:border-gray-300 hover:shadow-sm"}`}
      aria-label={`Project: ${project.title}`}
    >
      {/* ── META BAR ──────────────────────────────────────────────────────── */}
      <div className={`flex items-center justify-between px-6 py-3 border-b
        ${isDark ? "border-wire" : "border-wire-light"}`}>
        <span className={`font-mono text-xs tracking-widest
          ${isDark ? "text-stone-600" : "text-gray-400"}`}>
          {project.id}
        </span>
        <span className="tag">{project.category}</span>
      </div>

      {/* ── TWO-COLUMN LAYOUT ─────────────────────────────────────────────── */}
      <div className={`lg:grid lg:grid-cols-[1fr_1fr] lg:divide-x
        ${isDark ? "lg:divide-wire" : "lg:divide-wire-light"}`}>

        {/* LEFT — Image gallery
            ─────────────────────────────────────────────────────────────────
            Images load from /public/images/projects/
            To swap: update src values in src/data/portfolio.js
            To add more slides: append objects to the images[] array
            ───────────────────────────────────────────────────────────────── */}
        <div className={`border-b lg:border-b-0
          ${isDark ? "border-wire" : "border-wire-light"}`}>
          {project.images && project.images.length > 0 ? (
            <ImageGallery
              images={project.images}
              projectTitle={project.title}
            />
          ) : (
            /* Fallback if no images provided */
            <div
              className={`w-full flex items-center justify-center
                ${isDark ? "bg-ink-900" : "bg-paper-100"}`}
              style={{ aspectRatio: "16/9" }}
            >
              <span className={`font-mono text-xs tracking-wider
                ${isDark ? "text-stone-700" : "text-gray-300"}`}>
                no preview
              </span>
            </div>
          )}
        </div>

        {/* RIGHT — Description */}
        <div className="flex flex-col">

          {/* Title block */}
          <div className={`p-6 lg:p-8 border-b
            ${isDark ? "border-wire" : "border-wire-light"}`}>
            <h3 className={`font-display font-bold text-xl lg:text-2xl leading-snug mb-1
              ${isDark ? "text-stone-200" : "text-gray-900"}`}>
              {project.title}
            </h3>
            {project.subtitle && (
              <p className={`text-sm mb-5
                ${isDark ? "text-stone-500" : "text-gray-500"}`}>
                {project.subtitle}
              </p>
            )}
            {/* Tech stack */}
            <div className="flex flex-wrap gap-2" role="list" aria-label="Technology stack">
              {project.stack.map((t) => (
                <span key={t} role="listitem"
                  className="tag text-accent-glow border-ink-600">
                  {t}
                </span>
              ))}
            </div>
          </div>

          {/* Problem / Solution */}
          <div className="p-6 lg:p-8 grid sm:grid-cols-2 lg:grid-cols-1 xl:grid-cols-2 gap-6 flex-1">
            <div>
              <p className={`font-mono text-xs uppercase tracking-wider mb-2
                ${isDark ? "text-stone-600" : "text-gray-400"}`}>
                Problem
              </p>
              <p className={`text-sm leading-relaxed
                ${isDark ? "text-stone-400" : "text-gray-600"}`}>
                {project.problem}
              </p>
            </div>
            <div>
              <p className={`font-mono text-xs uppercase tracking-wider mb-2
                ${isDark ? "text-stone-600" : "text-gray-400"}`}>
                Solution
              </p>
              <p className={`text-sm leading-relaxed
                ${isDark ? "text-stone-400" : "text-gray-600"}`}>
                {project.solution}
              </p>
            </div>
          </div>

          {/* Expand toggle */}
          <div className={`px-6 lg:px-8 py-4 border-t
            ${isDark ? "border-wire" : "border-wire-light"}`}>
            <button
              onClick={() => setExpanded(!expanded)}
              className={`font-mono text-xs transition-colors flex items-center gap-2 tracking-wider
                ${isDark
                  ? "text-stone-500 hover:text-accent-glow"
                  : "text-gray-400 hover:text-accent-glow"}`}
              aria-expanded={expanded}
              aria-controls={`details-${project.id}`}
            >
              {expanded ? "— Collapse Details" : "+ Show Technical Details"}
            </button>
          </div>
        </div>
      </div>

      {/* ── EXPANDABLE DETAILS ────────────────────────────────────────────── */}
      {expanded && (
        <div
          id={`details-${project.id}`}
          className={`border-t px-6 lg:px-8 py-8 grid sm:grid-cols-2 gap-8
            ${isDark
              ? "border-wire bg-ink-900/50"
              : "border-wire-light bg-paper-100/50"}`}
        >
          <div>
            <p className={`font-mono text-xs uppercase tracking-wider mb-4
              ${isDark ? "text-stone-600" : "text-gray-400"}`}>
              Key Features
            </p>
            <ul className="space-y-3" role="list">
              {project.features.map((f) => (
                <li key={f} className={`flex items-start gap-3 text-sm
                  ${isDark ? "text-stone-400" : "text-gray-600"}`}>
                  <span className="text-accent-glow mt-0.5 text-xs flex-shrink-0" aria-hidden="true">◆</span>
                  {f}
                </li>
              ))}
            </ul>
          </div>
          <div>
            <p className={`font-mono text-xs uppercase tracking-wider mb-4
              ${isDark ? "text-stone-600" : "text-gray-400"}`}>
              Technical Highlights
            </p>
            <ul className="space-y-3" role="list">
              {project.highlights.map((h) => (
                <li key={h} className={`flex items-start gap-3 text-sm
                  ${isDark ? "text-stone-400" : "text-gray-600"}`}>
                  <span className="text-accent-glow mt-0.5 text-xs flex-shrink-0" aria-hidden="true">◆</span>
                  {h}
                </li>
              ))}
            </ul>
          </div>
        </div>
      )}
    </article>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Projects section
// ─────────────────────────────────────────────────────────────────────────────
export default function Projects() {
  const { theme } = useTheme();
  const isDark = theme === "dark";

  return (
    <section
      id="projects"
      className={`py-28 border-t transition-colors duration-300
        ${isDark ? "border-wire bg-ink-950" : "border-wire-light bg-paper-50"}`}
    >
      <div className="max-w-6xl mx-auto px-6">
        <div className="mb-14">
          <p className="section-label mb-4">Projects</p>
          <h2 className={`section-title text-3xl sm:text-4xl lg:text-5xl max-w-xl
            ${isDark ? "text-stone-200" : "text-gray-900"}`}>
            Selected work.<br />
            <span className={isDark ? "text-stone-500" : "text-gray-400"}>
              Architecture documented.
            </span>
          </h2>
          <p className={`text-sm mt-4 font-mono
            ${isDark ? "text-stone-500" : "text-gray-400"}`}>
            Use arrow buttons or ← → keys to navigate screenshots. Expand each card for technical details.
          </p>
        </div>

        <div className="space-y-6">
          {projects.map((project) => (
            <ProjectCard key={project.id} project={project} />
          ))}
        </div>
      </div>
    </section>
  );
}
